CREATE TABLE conta (id INTEGER PRIMARY KEY, saldo INTEGER);
BEGIN TRANSACTION;
INSERT INTO conta VALUES (1, 500);
INSERT INTO conta VALUES (2, 300);
COMMIT;
BEGIN TRANSACTION;
UPDATE conta SET saldo = saldo - 200 WHERE id = 1;
UPDATE conta SET saldo = saldo + 200 WHERE id = 2;
ROLLBACK;
BEGIN TRANSACTION;
UPDATE conta SET saldo = saldo - 50 WHERE id = 1;
UPDATE conta SET saldo = saldo + 50 WHERE id = 2;
COMMIT;
SELECT saldo FROM conta WHERE id = 2;

